INSERT INTO app.gmdn_categories VALUES('4941',NULL,'Device Function','Categories that group medical devices by clinical functionality or paraclinical context.',NULL),
('4',NULL,'Anatomical Specialty','Categories for device names above the level of the GMDN Term arranged by anatomical-based clinical panel or anatomical grouper.',NULL),
('3',NULL,'Names Index','Categories for device names above the level of the GMDN Term.',NULL),
('898',NULL,'Invasiveness/Implantability','Categories that group medical devices by various types and degrees of device invasion into the body, including implants and implant types.',NULL),
('890',NULL,'Use Frequency','Categories that describe various types of frequencies of device use.',NULL),
('888',NULL,'Power','Categories that group medical devices based on power input (active or non-active).',NULL),
('887',NULL,'Materials/Drug-Device Combination','Categories that group medical devices by their physical constituents, relating to material types which are clinical significance with respect to device intended use, and pharmaceutical agent inclusion (drug-device combination products).',NULL),
('1',NULL,'Featured Attributes','Categories that describe many different device characteristics.',NULL),
('12669','CT2985','Active','Devices dependent on a source of energy other than that generated by the human body, or by gravity, and which function by changing or converting that energy (includes software).','888'),
('6711','CT2727','Active implant devices/ancillaries','Active implantable devices and devices fully or substantially dedicated to the introduction and/or function of an active implantable device.','4941'),
('49','CT145','Cardiovascular devices','Devices fully or substantially dedicated to the measurement or monitoring of physical and functional cardiovascular parameters, or to the treatment and management of diseases/disorders of the heart and blood vessels. ','4'),
('10523','CT2406','Implantable','Devices intended to be totally or partially introduced into the human body or body orifice (surgically or medically) and remain for longer than 30 days.','898'),
('13712','CT3079','Pharmaceutical/Antimicrobial','Medical devices that include a pharmaceutical agent (i.e., drugs, medication) or an antimicrobial material (e.g., silver), for device types where the antimicrobial inclusion is deemed clinically significant (e.g., high infection risk devices, high-volume devices).','887'),
('12859','CT209','Human-derived','Devices containing materials derived from human tissues that have particular clinical significance with respect to device intended use.','887'),
('12675','CT2986','Non-active','Devices which either: 1) do not depend on a source of energy, or 2) only rely on energy created by the human body or gravity, or 3) transmit energy, substances or other elements between an active device and a patient without any significant change.','888'),
('6490','CT2722','Pulmonary devices','Devices fully or substantially dedicated to the diagnosis, monitoring, or treatment of medical conditions of the airways and pulmonary structures/organs of the chest cavity (e.g., lungs, pleura), including devices intended for ventilation and inhalation protection.','4'),
('896','CT983','Surgical invasive','Devices introduced into the body involving physical penetration of tissues.','898'),
('5275','CT1007','Tissue reparation devices','Patient-contact devices/materials intended to remain in situ after application to repair injured, defective, or disordered body tissues through mending, replacement, reconstruction, or promotion of tissue restoration/regeneration/normalization (excludes surgical instruments).','4941'),
('12676','CT2987','Active/Non-active undefined','Device collections with a primary intended use that may be substantially fulfilled without dependence on a source of energy (non-active) but which may include active components.','888'),
('12857','CT210','Animal-derived','Devices containing materials derived from animal tissues or products that have particular clinical significance with respect to device intended use.','887'),
('933','CT1002','Gastro-urological devices','Devices fully or substantially dedicated to the evaluation, diagnosis, and/or treatment/management of diseases or conditions of the gastrointestinal and urological systems. ','4'),
('12860','CT2344','Microbe-derived','Devices containing probiotic microorganisms or containing materials synthesized by microorganisms (biosynthetic) that serve as a principal device constituent and have particular clinical significance with respect to device intended use.','887'),
('897','CT984','Non-surgical invasive','Devices introduced into the body without penetration, or involving extremely superficial penetration (e.g., abrasion), of body tissues, introduction is typically through an orifice.','898'),
('6494','CT1274','Surgical/Invasive procedure instrumentation','Instruments, systems, and components intended to be used as functional tools during, or to prepare for, a surgical invasive or non-surgical invasive (e.g., oral) therapeutic clinical procedure (excludes devices designed to deliver energy for non-surgical applications).','4941'),
('5983','CT366','Endoscopic devices','Devices fully or substantially dedicated to endoscopic procedures, i.e., advancement into a natural or surgically-created body opening, whether through the working channel of an endoscope or not, for examination, diagnosis, and/or intervention.','4941'),
('12904','CT3006','Implantable inorganic material','Implantable devices containing materials from non-living sources, or in some cases, containing materials that have been synthesized from living-source materials.','887'),
('936','CT1005','Neurological devices','Devices fully or substantially dedicated to the evaluation, diagnosis, monitoring, and/or treatment/management of neurological disorders and diseases, or performing clinical evaluation/treatment through nerves.','4'),
('9057','CT2818','Catheterization/Cannulation/Fluid path devices','Devices dedicated to catheterization/cannulation procedures and/or that provide a channel to direct the flow of fluids (e.g., infusion, injection, drainage, suction, shunting) for procedural, diagnostic, or therapeutic applications (excludes delivery of gases).','4941'),
('134','CT230','Ophthalmic devices','Devices fully or substantially dedicated to the evaluation, diagnosis, and/or treatment/management of diseases and disorders of the eye. ','4'),
('3343','CT609','Wax materials','Devices manufactured containing natural or mineral wax that have clinical significance with respect to device intended use.','887'),
('12852','CT204','High volume Latex','High-contact/invasive devices manufactured in extremely high volumes (condoms, gloves) containing natural rubber latex (NRL) derived from plants (e.g., the rubber tree).','887'),
('85','CT181','Obstetrical/Gynaecological devices','Devices fully or substantially dedicated to the evaluation, diagnosis, and/or treatment/management of diseases or conditions in women, especially those of the genitourinary tract and those associated with conception, pregnancy, and childbirth.','4'),
('6493','CT2724','Tissue/Fluid collection and preservation devices','Devices fully or substantially dedicated to the collection and/or preservation of tissues or body fluids usually intended for subsequent diagnostic or therapeutic applications such as in vitro diagnostics, forensics, transplantation, or donation.','4941'),
('4943','CT996','Anaesthesia and ventilation devices','Devices fully or substantially dedicated to the diagnosis or treatment of respiratory conditions including delivery of respiratory/ventilatory support and/or general, local, or regional anaesthesia.','4941'),
('932','CT1001','Ear/Nose/Throat (ENT) devices','Devices fully or substantially dedicated to the evaluation, diagnosis, and/or treatment/management of disorders and diseases of the ears, nose, and throat.','4'),
('9024','CT2816','Circulatory assistive/bypass devices','Devices intended to replace/assist the function of the heart or otherwise facilitate improved blood circulation in therapeutic or procedural applications.','4941'),
('937','CT1006','Orthopaedic devices','Devices fully or substantially dedicated to the evaluation, diagnosis, and/or treatment/management of diseases and disorders of the skeletal system. ','4'),
('9038','CT2817','Autologous blood processing devices','Devices intended to be used to circulate, separate, manage, develop, and/or administer autologous blood/blood products, or support autologous blood patients, typically during a therapeutic procedure.','4941'),
('926','CT998','Dental/Maxillofacial devices','Devices fully or substantially dedicated to the diagnosis, prevention, monitoring, treatment, and/or alleviation of oral and maxillofacial diseases/disorders.','4'),
('679','CT775','Dermatological and soft-tissue reconstructive/cosmetic devices','Devices fully or substantially dedicated to diagnosis or treatment of dermal conditions or the treatment of soft-tissue diseases and injuries by means of plastic/reconstructive surgery.','4'),
('5035','CT999','Radiological devices','Devices dedicated to diagnostic radiology or radiation therapy (therapy using ionizing radiation).','4941'),
('6492','CT2723','Energy-based therapy equipment (non-radiological/non-surgical)','Equipment fully or substantially dedicated to the utilization of non-ionizing radiation, ultrasound, heat, light, electricity, and magnetism for therapeutic applications (excludes radiological, surgical, and active implant applications).','4941'),
('6710','CT2726','Physiological monitoring/measuring devices','Devices fully or substantially dedicated to the monitoring or measuring of a patient physiological parameter(s) or condition(s).','4941'),
('8861','CT2795','Physical examination equipment','Devices (non-radiological, non-endoscopic) intended for non-surgical patient anatomical examination/measurement, general or specialized, or types of patient physiological assessment associated with a physical examination (e.g., hearing, vision, body acoustics).','4941'),
('11813','CT275','Biomechanical rehabilitation equipment','Equipment designed to be used as part of physical rehabilitation through exercise, biomechanical function analysis, or rehabilitative treatments involving tissue mechanical manipulation and energy application methods.','4941'),
('8950','CT2811','Bariatric therapy devices','Surgical and non-surgical devices designed to treat overweight/obese patients through various means primarily involving reduction of food intake and/or nutrient absorption.','4941'),
('11189','CT149','General hospital devices','Clinically-supportive devices that have patient examination/treatment, healthcare provider assistive, and/or general care applications, and devices that contribute to the general infrastructure or functionality of a healthcare facility.','4941'),
('11091','CT1000','Disability-living products','Devices dedicated to assist a patient in managing/treating an impairment, disability, or handicap outside a clinical setting.','4941'),
